// Package billingdemo is the demonstration billing system. It mirrors invoices
// into deals through the ingress port, as its service member. A paid invoice
// moves its deal to the won stage without anyone typing.
//
// It is the reference for a unit that writes deals back to the core. The
// invoices are generated by the unit rather than read from a vendor. Every
// write goes through the core's own deal stores. A figure a member edited is
// left as it is, unless an admin lets this unit overwrite it.
package billingdemo

import (
	"embed"

	"github.com/margince/margince/backend/pkg/extension"
)

//go:embed migrations
var migrations embed.FS

// system is the unit's key for its provider on every deal it lands.
const system = "billing-demo"

// feedSecret is the key filed under the service member. Filing it is the
// operator's act of agreeing that the feed lands records as that member.
const feedSecret = "feed"

// New returns the unit's declaration.
func New() extension.Extension {
	return extension.Extension{
		Name:        "billing-demo",
		Version:     "1.0.0",
		Description: "Demonstration billing system that moves a deal to won when its invoice is paid, written back through the core's own deal stores.",
		Migrations:  migrations,
		Secrets:     []extension.SecretsRequest{{Key: "feed", Scope: extension.SecretScopeUser}},
		Tools: []extension.Tool{
			{Name: "billing_demo_connect", Handle: connect},
			{Name: "billing_demo_update_invoice", Handle: updateInvoice},
			{Name: "billing_demo_status", Handle: status},
		},
		Ingress: []extension.IngressSource{{
			System: "billing-demo",
			Lands:  []extension.RecordKind{extension.KindDeal},
		}},
		Jobs:           []extension.Job{{Name: "sync", Handle: syncTick}},
		FailureClasses: failureClasses,
	}
}

var failureClasses = []extension.FailureClass{classSyncFailed}

var classSyncFailed = extension.FailureClass{
	Class:    "sync_failed",
	Sentence: "the billing-demo sync failed for a cause this unit does not classify",
	Remedy:   "Read the cause in this job's process log.",
}
